// dropStaleEntireHooks removes Entire-owned hooks whose command is not want,
// leaving foreign hooks and the current command untouched.
//
// This runs on every install, not just --force. Without it, a hook written by an
// older version survives alongside the freshly added one and keeps firing —
// which for the removed local-dev mode means a script inside the working tree
// still executes on every agent turn. Returning the input unchanged when the
// only Entire hook present is already `want` keeps installs idempotent.
func dropStaleEntireHooks(matchers []FactoryHookMatcher, want string) []FactoryHookMatcher {
	result := make([]FactoryHookMatcher, 0, len(matchers))
	for _, matcher := range matchers {
		filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
		for _, hook := range matcher.Hooks {
			if isEntireHook(hook.Command) && hook.Command != want {
				continue
			}
			filteredHooks = append(filteredHooks, hook)
		}
		if len(filteredHooks) > 0 {
			matcher.Hooks = filteredHooks
			result = append(result, matcher)
		}
	}
	return result
}

