// dropStaleEntireHooks removes Entire-owned hooks whose command is not one of
// want, leaving foreign hooks and the current commands untouched. want is a set
// because one hook list can hold several Entire commands (PostToolUse carries
// both post-task and post-todo).
//
// This runs on every install, not just --force. Without it, a hook written by an
// older version survives alongside the freshly added one and keeps firing —
// which for the removed local-dev mode means a script inside the working tree
// still executes on every agent turn.
//
// It reports whether anything was dropped, because the caller must write the
// file even when no hook was *added*: a machine can hold both a stale and a
// current hook at once, and skipping the write would leave the stale one there.
// Reporting false when every Entire hook present is already wanted keeps
// installs idempotent.
func dropStaleEntireHooks(matchers []ClaudeHookMatcher, want ...string) ([]ClaudeHookMatcher, bool) {
	result := make([]ClaudeHookMatcher, 0, len(matchers))
	dropped := false
	for _, matcher := range matchers {
		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
		for _, hook := range matcher.Hooks {
			if isEntireHook(hook.Command) && !slices.Contains(want, hook.Command) {
				dropped = true
				continue
			}
			filteredHooks = append(filteredHooks, hook)
		}
		if len(filteredHooks) > 0 {
			matcher.Hooks = filteredHooks
			result = append(result, matcher)
		}
	}
	return result, dropped
}

